 const giftIds=['5655','5269','6064','5827'],giftNames=['ROSE','TIKTOK','GG','ICE CREAM'];
 function addScenery(){const palms=[],leaves=[],mountains=[],arches=[];for(let z=-80;z<90;z+=18)for(const side of [-1,1]){const x=side*(roadWidth/2+4);palms.push({x,z,y:2.5,scale:[.32,5,.32]});for(let a=0;a<3;a++)leaves.push({x,z,y:5,scale:[3.7,.18,.5],yaw:a*Math.PI/3});mountains.push({x:side*(roadWidth/2+12),z,y:2.5,scale:[5,6+Math.abs(z)%4,5]});arches.push({x:side*(roadWidth/2+1),z,y:3.2,scale:[.25,6.4,.28]})}for(let z=-80;z<90;z+=18)arches.push({x:0,z,y:6.4,scale:[roadWidth+2,.22,.28]});instance(mat('#7d5c43',.1,.8),palms,'coast');instance(mat('#299161',.1,.8),leaves,'coast');instance(mat('#cf9865',.05,1),mountains,'desert',new THREE.ConeGeometry(1,1,5));instance(new THREE.MeshBasicMaterial({color:'#51e0f3'}),arches,'tunnel')}
 function signTexture(text,color){const c=document.createElement('canvas');c.width=512;c.height=256;const x=c.getContext('2d');x.fillStyle='#082333';x.fillRect(0,0,512,256);x.strokeStyle=color;x.lineWidth=14;x.strokeRect(7,7,498,242);x.fillStyle=color;x.font='900 53px Arial';x.textAlign='center';x.textBaseline='middle';const words=text.split('|');words.forEach((word,i)=>x.fillText(word,256,90+i*77));const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;return tex}
 function addSigns(){const textures=[signTexture('TAP TO|LIKE','#ff7899'),signTexture('SHARE|THE LIVE','#75f3e2')];for(let i=0;i<4;i++){const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:textures[i%2],depthWrite:false}));sprite.scale.set(5,2.5,1);sprite.userData={label:i%2?'SHARE THE LIVE':'TAP TO LIKE',x:(i%2?1:-1)*(roadWidth/2+4.6),start:-55+i*30};world.add(sprite);signs.push(sprite)}}
 function addRoadGifts(index){for(let i=0;i<2;i++){const type=(index+i)%4;let texture=giftTextureCache[type];if(!texture){texture=new THREE.TextureLoader().load('/gifts/'+giftIds[type]+'.png');texture.colorSpace=THREE.SRGBColorSpace;giftTextureCache[type]=texture}const object=new THREE.Group(),ring=mesh(new THREE.TorusGeometry(.58,.07,6,20),new THREE.MeshBasicMaterial({color:'#ffe781'}));ring.rotation.x=-Math.PI/2;object.add(ring);const icon=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,depthWrite:false}));icon.position.y=.65;icon.scale.set(1.25,1.25,1);object.add(icon);world.add(object);roadGifts.push({index,slot:i,type,object,icon,ring,threshold:0})}}
 function showEvent(text,now){eventHud.textContent=text;eventHud.hidden=false;eventUntil=now+2300;lastEventAt=now}
 function sampleMotion(){const now=Date.now()+(window.__raceServerOffset||0);motionState=motion.sample(state,now);if(lastRound!==state.round){lastRound=state.round;pickupTotal=0;eventUntil=0;eventHud.hidden=true;players.forEach(p=>{p.raceZ=0;p.collectUntil=0})}for(const e of motionState.events){window.dispatchEvent(new CustomEvent('race-visual-event',{detail:e}));if(e.type==='overtake'){showEvent('OVERTAKE · '+e.name+' · P'+e.from+' → P'+e.to,now);shotUntil=performance.now()+3200;lastShot=performance.now()}else if(e.type==='pickup'){pickupTotal+=e.count;const p=players[e.index];if(p)p.collectUntil=now+650;if(now-lastEventAt>2500)showEvent(giftNames[(e.index+Math.floor(state.slots[e.index].distance/(state.settings.step*4)))%4]+' PICKUP · CAR '+(e.index+1),now)}}}
 function applyTheme(elapsed){const theme=themes[Math.floor(elapsed/35)%themes.length];if(theme.name===themeName)return;themeName=theme.name;scene.background.set(theme.sky);scene.fog.color.set(theme.sky);groundMesh.material.color.set(theme.ground);roadMesh.material.color.set(theme.road);for(const stream of streams)stream.mesh.visible=stream.theme==='common'||stream.theme===theme.key;sceneHud.textContent=theme.name}
 function updateRoadDetails(now,t,running){for(const sign of signs){const z=((sign.userData.start+scroll+90)%180)-90;sign.position.set(centerAt(z)+sign.userData.x,3.4,z)}let fastest=null;for(const [index,row]of motion.rows)if(!fastest||row.pace>fastest.row.pace)fastest={index,row};paceHud.textContent=fastest&&fastest.row.pace>0?'FASTEST · CAR '+(fastest.index+1)+' · '+fastest.row.pace.toFixed(1)+' PTS/s':'TAP TO ACCELERATE';pickupHud.textContent='ROAD PICKUPS '+pickupTotal;eventHud.hidden=now>=eventUntil;for(const gift of roadGifts){const p=players[gift.index],driver=state.slots[gift.index];if(!p||!driver){gift.object.visible=false;continue}gift.object.visible=true;const interval=state.settings.step*4,next=(Math.floor((p.distance||0)/interval)+1+gift.slot)*interval;gift.threshold=next;const type=(gift.index+Math.round(next/interval))%4;if(gift.type!==type&&giftTextureCache[type]){gift.type=type;gift.icon.material.map=giftTextureCache[type];gift.icon.material.needsUpdate=true}const ahead=(next-(p.distance||0))/state.settings.step*1.65,z=p.group.position.z-ahead;gift.object.position.set(centerAt(z)+(gift.index-(state.settings.cars-1)/2)*3.2,.12+Math.sin(t*.003+gift.index)*.08,z);gift.ring.rotation.z=t*.001;gift.icon.material.rotation=Math.sin(t*.001+gift.index)*.12;if(now<(p.collectUntil||0)&&gift.slot===0){const f=1-(p.collectUntil-now)/650;gift.object.position.lerp(new THREE.Vector3(p.group.position.x,1.4,p.group.position.z),f);gift.object.scale.setScalar(1-f*.8);gift.icon.material.opacity=1-f*.8}else{gift.object.scale.setScalar(1);gift.icon.material.opacity=1}}}

 function portraitSubject(elapsed){const people=state.slots.slice(0,state.settings.cars).map((p,i)=>({p,i})).filter(x=>x.p&&!x.p.isDemo),available=people.length?people:state.slots.slice(0,state.settings.cars).map((p,i)=>({p,i})).filter(x=>x.p),cycle=state.round+':'+Math.max(0,Math.floor((elapsed-10)/42));if(!available.length)return null;if(cycle!==portraitCycle||!available.some(x=>x.i===portraitIndex)){portraitCycle=cycle;portraitIndex=available[Math.max(0,Math.floor((elapsed-10)/42))%available.length].i}return state.slots[portraitIndex]}
 function updatePortrait(elapsed,running){const show=mode==='portrait'&&running,driver=show?portraitSubject(elapsed):null;portraitCard.hidden=!driver;document.body.classList.toggle('portrait-scene',!!driver);if(!driver)return;const key=JSON.stringify([driver.id,driver.name,driver.avatar,driver.countryFlag]);if(key!==portraitKey){portraitKey=key;portraitCard.querySelector('.driver-spotlight-name').textContent=driver.name;const image=portraitCard.querySelector('img'),fallback=portraitCard.querySelector('b');fallback.textContent=(driver.name||'?').slice(0,1);image.hidden=!driver.avatar;image.referrerPolicy='no-referrer';image.alt=driver.name;if(driver.avatar)image.src=driver.avatar;image.onerror=()=>{image.hidden=true};renderFlag(portraitCard.querySelector('i'),driver.isDemo?state.flags[portraitIndex]:driver.countryFlag)}const rank=motion.rows.get(portraitIndex)?.rank||portraitIndex+1,points=Math.floor(driver.distance/state.settings.step);portraitCard.querySelector('.driver-spotlight-meta').textContent='CAR '+(portraitIndex+1)+' · P'+rank+' · '+points+' PTS'}
 function screenBounds(i){const p=players[i];if(!p||!camera)return null;const b=new THREE.Box3().setFromObject(p.group),points=[];for(const x of [b.min.x,b.max.x])for(const y of [b.min.y,b.max.y])for(const z of [b.min.z,b.max.z]){const q=new THREE.Vector3(x,y,z).project(camera);points.push({x:(q.x*.5+.5)*root.clientWidth,y:(-.5*q.y+.5)*root.clientHeight})}return {width:Math.max(...points.map(p=>p.x))-Math.min(...points.map(p=>p.x)),height:Math.max(...points.map(p=>p.y))-Math.min(...points.map(p=>p.y))}}
 window.Race3D={update,resize,get renderer(){return renderer},get players(){return players},get cameraMode(){return mode},get curve(){return slopeAt(0)},get motion(){return motion},get theme(){return themeName},get portrait(){return state?.slots[portraitIndex]||null},get collected(){return pickupTotal},get collectibles(){return roadGifts},get billboards(){return signs},setCamera(mode,seconds=5){if(shots[mode])forced={mode,until:performance.now()+seconds*1000}},screenBounds};window.addEventListener('resize',resize);
